// Lane S3: the world playlist (playlist/engine.mjs + one chunk per piece, generated by tools/score/build-playlist.mjs from
// vendor/sim-score) loads without Tone doing anything, registers every listed piece once, and each piece composes its first
// cycles (notes, no audio). Lane SCORE: the four optional engine modules load too, the vendored copy matches its
// provenance, and the generated chunks match a fresh build from it.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createPlaylistScore, loadPiece, PLAYLIST } from './playlist/engine.mjs';
import { musicDb } from '../gen-mesh/music.ts';
import { buildPlaylist, OUT, PLAYLIST as BUILDER_PLAYLIST } from '../../../../tools/score/build-playlist.mjs';
import { checkVendored } from '../../../../tools/score/sync-sim-score.mjs';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const inertTone = new Proxy({}, { get: () => function inert() { return undefined; } });
type Piece = { id: string; compose(a: object): { events?: unknown[]; state?: object } };
type Sim = { pieces: Piece[]; Conductor: unknown; theory: { rng(seed: number): { fork(n: number): unknown } }; phrasing?: object; spc?: object; dialogue?: object; groove?: object };
async function loaded() {
  const Sim = createPlaylistScore(inertTone) as unknown as Sim;
  for (const id of PLAYLIST) (await loadPiece(id)).default(Sim as never, inertTone);
  return Sim;
}

test('the playlist registers each of its pieces once, in order, without touching Tone', async () => {
  const Sim = await loaded();
  assert.equal(PLAYLIST.length, 40);
  assert.equal(new Set(PLAYLIST).size, PLAYLIST.length);
  assert.deepEqual([...PLAYLIST], BUILDER_PLAYLIST);
  assert.deepEqual(Sim.pieces.map((p) => p.id), [...PLAYLIST]);
  assert.equal(typeof Sim.Conductor, 'function');
  await assert.rejects(loadPiece('no-such-piece'), /not on the playlist/);
});

test('the four optional engine modules load under an inert Tone, and their demo pieces are on the playlist', () => {
  const Sim = createPlaylistScore(inertTone) as unknown as Sim;
  for (const [m, demo] of [['phrasing', 'night-approach'], ['spc', 'headland'], ['dialogue', 'evening-rounds'], ['groove', 'velour']] as const) {
    assert.equal(typeof Sim[m], 'object', `Sim.${m}`);
    assert.ok(PLAYLIST.includes(demo), demo);
  }
});

test('every piece composes its first three cycles', async () => {
  const Sim = await loaded();
  for (const p of Sim.pieces) {
    const rng = Sim.theory.rng(7); let state = {}, notes = 0;
    for (let cycle = 0; cycle < 3; cycle++) { const r = p.compose({ cycle, rng: rng.fork(cycle), state, T: Sim.theory }) ?? {}; state = r.state ?? state; notes += r.events?.length ?? 0; }
    assert.ok(notes > 20, `${p.id}: ${notes} events`);
  }
});

test('the vendored Sim Score matches its provenance hashes', () => {
  const { prov, problems } = checkVendored();
  assert.deepEqual(problems, []);
  assert.match(prov.source.commit, /^[0-9a-f]{40}$/);
  assert.ok(prov.files.length > 100);
});

test('the generated playlist chunks match a fresh build from the vendored copy', () => {
  const { files, commit } = buildPlaylist();
  assert.equal(JSON.parse(readFileSync(join(OUT, 'BUILD.json'), 'utf8')).source.commit, commit);
  for (const [p, text] of files) assert.equal(readFileSync(join(OUT, p), 'utf8'), text, `${p} is stale: node tools/score/build-playlist.mjs`);
});

test('music level follows the master volume; zero is silence', () => {
  assert.equal(musicDb(0), -Infinity);
  assert.ok(musicDb(0.32) < -9 && musicDb(0.32) > -11);
  assert.equal(musicDb(1), 0);
});
